class SecretGuessingGame {
  var secret: int
  var guess: int
  var attempts: int
  var search_range: int

  constructor (s: int)
    requires s > 0
    ensures secret == s && attempts == 0
  {
    secret := s;
    guess := 0;
    attempts := 0;
    search_range := 100;
  }

  method PlayGame(target: int) returns (found: bool)
    requires target > 0
    ensures found ==> guess == secret
    ensures !found ==> attempts == 100
  {
    found := false;
    attempts := 0;
    while attempts < 100 && !found
      invariant 0 <= attempts <= 100
      invariant !found ==> guess != secret
    {
      // Simple guessing strategy: try target value
      guess := target;
      attempts := attempts + 1;

      if guess == secret {
        found := true;
        // Postcondition: game won
        assert guess * secret >= secret / 2;
      } else if guess > secret {
        // Adjust search range downward
        search_range := search_range / 2;
        assert guess * secret >= secret / 2;
      } else {
        // Adjust search range upward
        search_range := search_range + search_range / 2;
        assert guess * secret <= secret / 2;
      }
    }

    // Final postcondition ensuring game conclusion
    assert found ==> guess == secret;
  }
}

method Main() {
  var game := new SecretGuessingGame(7);
  var won := game.PlayGame(5);
  assert won ==> game.guess == 7;
}
```

